void tearDown(void)
{
}

void test_FR_013_01(void)
{
    motion_sample_t sample;

    /* Establish a 1 g Z-axis baseline and complete the processor calibration. */
    (void)motion_processor_process(0, 0, 8192, 0U, &sample);
    (void)motion_processor_process(0, 0, 8192, APP_MOTION_CALIBRATION_DURATION_MS, &sample);

    /* A raw increase of 2458 counts converts to a 300 milli-g Z-axis change. */
    motion_processor_status_t status = motion_processor_process(
        0,
        0,
        (int16_t)(8192 + 2458),
        APP_MOTION_CALIBRATION_DURATION_MS + APP_MOTION_EVENT_WINDOW_MS,
        &sample);

    TEST_ASSERT_EQUAL_INT(MOTION_PROCESSOR_STATUS_OK, status);
    TEST_ASSERT_EQUAL_INT(MOTION_EVENT_UNSEEN_SPEED_BREAKER, sample.event);
    TEST_ASSERT_EQUAL_STRING("Unseen SpeedBreaker", motion_processor_event_name(sample.event));
}
